local NEW_TITLE = "NEXUS XIT V2"
local WA_TEXT   = "JOIN WHATSAPP NEXUS"
local WA_LOW    = WA_TEXT:lower()
local WA_LINK   = "https://whatsapp.com/channel/0029VbEbBdNHQbS4AvTSjF2C"
local WA_ICON   = "rbxassetid://7985491978" -- ID Logo WhatsApp

local Players      = game:GetService("Players")
local CoreGui      = game:GetService("CoreGui")
local TweenService = game:GetService("TweenService")
local LP = Players.LocalPlayer
local conts = {CoreGui}
local PG = LP:FindFirstChildOfClass("PlayerGui") or LP:WaitForChild("PlayerGui", 10)
if PG then table.insert(conts, PG) end
if gethui then pcall(function() table.insert(conts, gethui()) end) end

local function notify(t)
    pcall(function()
        game:GetService("StarterGui"):SetCore("SendNotification", {Title = NEW_TITLE, Text = tostring(t), Duration = 5})
    end)
end

-- ==========================================
-- 1. BAJAK NOTIFIKASI VXEZE
-- ==========================================
pcall(function()
    local SG = game:GetService("StarterGui")
    local oldSetCore = SG.SetCore
    SG.SetCore = function(self, core, args)
        if core == "SendNotification" and type(args) == "table" then
            if args.Title and string.find(string.lower(args.Title), "vxeze") then args.Title = NEW_TITLE end
            if args.Text and string.find(string.lower(args.Text), "vxeze") then 
                args.Text = args.Text:gsub("[Vv][Xx][Ee][Zz][Ee] Hub", "NEXUS XIT"):gsub("[Vv][Xx][Ee][Zz][Ee]", "NEXUS") 
            end
        end
        return oldSetCore(self, core, args)
    end
end)

