-- ==========================================
-- 3. FUNGSI PENDUKUNG
-- ==========================================
local function trim(s) return (s:gsub("^%s+", ""):gsub("%s+$", "")) end
local function isText(o) return o:IsA("TextLabel") or o:IsA("TextButton") end
local function getText(o)
    local ok, t = pcall(function() return o.Text end)
    if ok and type(t) == "string" then return t end
    return ""
end

local function isOurs(o)
    return o.Name == "NexusLogo" or o.Name == "NexusParticles" or o.Name == "NexusWA" or o.Name == "NexusHighlight"
        or string.find(o.Name, "Star_")
        or o:FindFirstAncestor("NexusLogo") ~= nil
        or o:FindFirstAncestor("NexusParticles") ~= nil
        or o:FindFirstAncestor("NexusWA") ~= nil
        or o:FindFirstAncestor("NexusHighlight") ~= nil
end

-- LOGIKA WARNA HIJAU (SAPU JAGAT)
local function mapColor(c, prop)
    local h, s, v = c:ToHSV()
    
    if s < 0.15 then 
        if prop == "TextColor3" and v > 0.8 then return Color3.fromRGB(255, 255, 255) end
        return c 
    end
    
    -- Rentang Hue (Cyan, Biru, Ungu, Magenta jadi Hijau)
    if h >= 0.35 and h <= 0.95 then 
        if prop == "TextColor3" or prop == "ImageColor3" then
            return Color3.fromRGB(50, 255, 100)
        else
            return Color3.fromHSV(0.33, math.min(s, 0.8), math.max(v, 0.3))
        end
    end
    return c
end

local function recolorProp(o, prop)
    local ok, cur = pcall(function() return o[prop] end)
    if not ok then return end
    
    if typeof(cur) == "Color3" then
        local n = mapColor(cur, prop)
        if n ~= cur then pcall(function() o[prop] = n end) end
    elseif typeof(cur) == "ColorSequence" then
        local pts, changed = {}, false
        for _, k in ipairs(cur.Keypoints) do
            local n = mapColor(k.Value, prop)
            if n ~= k.Value then changed = true end
            table.insert(pts, ColorSequenceKeypoint.new(k.Time, n))
        end
        if changed then pcall(function() o[prop] = ColorSequence.new(pts) end) end
    end
end

local recolored = setmetatable({}, {__mode = "k"})
local function recolorObject(o)
    if recolored[o] or isOurs(o) then return end
    recolored[o] = true
    local props = {}
    
    if o:IsA("GuiObject") then table.insert(props, "BackgroundColor3") end
    if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then table.insert(props, "TextColor3") end
    if o:IsA("ImageLabel") or o:IsA("ImageButton") then 
        local nm = o.Name:lower()
        if not (nm:find("avatar") or nm:find("headshot") or nm:find("thumb") or nm:find("user")) then
            table.insert(props, "ImageColor3") 
        end
    end
    if o:IsA("ScrollingFrame") then table.insert(props, "ScrollBarImageColor3") end
    if o:IsA("UIStroke") or o:IsA("UIGradient") then table.insert(props, "Color") end
    
    for _, prop in ipairs(props) do pcall(recolorProp, o, prop) end
end

-- ==========================================
-- 4. SISTEM HIGHLIGHT & GANTI IKON DISCORD
-- ==========================================
local currentHighlight = nil
local activeTab = nil

local function updateHighlight(clickedBtn)
    if activeTab == clickedBtn then return end
    activeTab = clickedBtn
    
    if currentHighlight and currentHighlight.Parent then currentHighlight:Destroy() end
    
    local box = Instance.new("Frame")
    box.Name = "NexusHighlight"
    box.Size = UDim2.new(1, 0, 1, 0)
    box.BackgroundColor3 = Color3.fromRGB(30, 80, 50)
    box.BackgroundTransparency = 0.4
    box.BorderSizePixel = 0
    box.ZIndex = clickedBtn.ZIndex - 1 
    box.Parent = clickedBtn
    Instance.new("UICorner", box).CornerRadius = UDim.new(0, 6)
    
    local stroke = Instance.new("UIStroke", box)
    stroke.Color = Color3.fromRGB(50, 255, 100)
    stroke.Thickness = 1.5
    stroke.Transparency = 0.2
    currentHighlight = box
end

local function hookTab(btn)
    if btn:GetAttribute("NexusTabHooked") then return end
    btn:SetAttribute("NexusTabHooked", true)
    btn.MouseButton1Click:Connect(function() updateHighlight(btn) end)
end

local function replaceDiscordIcon(btn)
    if btn:GetAttribute("NexusIconReplaced") then return end
    for _, v in ipairs(btn:GetDescendants()) do
        if v:IsA("ImageLabel") or v:IsA("ImageButton") then
            local img = tostring(v.Image):lower()
            local w = v.AbsoluteSize.X
            if img:find("discord") or img:find("dcd") or (w > 10 and w < 90) then
                v.Image = WA_ICON
                v.ImageColor3 = Color3.new(1, 1, 1)
                btn:SetAttribute("NexusIconReplaced", true)
                break
            end
        end
    end
end

local chatRows = {}

-- tutup celah bekas baris Global Chat: menu di bawahnya digeser naik (kalau sidebar tidak pakai layout otomatis)
local function closeGap(row)
    local parent = row.Parent
    if not parent then return end
    if parent:FindFirstChildOfClass("UIListLayout") or parent:FindFirstChildOfClass("UIGridLayout") then return end
    local rowY, rowH = row.AbsolutePosition.Y, row.AbsoluteSize.Y
    local step = row:GetAttribute("NexusStep")
    if not step then
        for _, sib in ipairs(parent:GetChildren()) do
            if sib ~= row and sib:IsA("GuiObject") and sib.AbsolutePosition.Y > rowY
                and math.abs(sib.AbsoluteSize.Y - rowH) <= 4 then
                local d = sib.AbsolutePosition.Y - rowY
                if not step or d < step then step = d end
            end
        end
        if not step then return end -- menu di bawahnya belum dibuat, dicoba lagi nanti
        row:SetAttribute("NexusStep", step)
    end
    for _, sib in ipairs(parent:GetChildren()) do
        if sib ~= row and sib:IsA("GuiObject") and not sib:GetAttribute("NexusShifted")
            and sib.AbsolutePosition.Y > rowY and math.abs(sib.AbsoluteSize.Y - rowH) <= 4 then
            sib:SetAttribute("NexusShifted", true)
            local p = sib.Position
            sib.Position = UDim2.new(p.X.Scale, p.X.Offset, p.Y.Scale, p.Y.Offset - step)
        end
    end
end

local function findChatRow(label)
    local cur = label
    while cur and cur.Parent and not cur:IsA("ScreenGui") do
        if cur:IsA("TextButton") or cur:IsA("ImageButton") then
            if #cur:GetDescendants() <= 25 then return cur end
            return nil
        end
        cur = cur.Parent
    end
    -- cadangan: baris berupa Frame biasa (induknya memuat menu "Steal" dan "Farm")
    cur = label
    while cur and cur.Parent and not cur:IsA("ScreenGui") do
        local p = cur.Parent
        local hasSteal, hasFarm = false, false
        for _, d in ipairs(p:GetDescendants()) do
            if isText(d) then
                local tx = trim(getText(d)):lower()
                if tx == "steal" then hasSteal = true elseif tx == "farm" then hasFarm = true end
            end
        end
        if hasSteal and hasFarm then
            if cur:IsA("GuiObject") and #cur:GetDescendants() <= 12 then return cur end
            return nil
        end
        cur = p
    end
    return nil
end

local function hideChatRow(cur)
    local parent = cur.Parent
    cur.Visible = false
    pcall(function() cur.BackgroundTransparency = 1 end)
    for _, v in ipairs(cur:GetDescendants()) do
        if v:IsA("GuiObject") then v.Visible = false end
    end
    if parent then
        local targetY = cur.AbsolutePosition.Y
        for _, sib in ipairs(parent:GetChildren()) do
            if sib ~= cur and sib:IsA("Frame") and math.abs(sib.AbsolutePosition.Y - targetY) < 20 then
                sib.Visible = false
                sib.BackgroundTransparency = 1
            end
        end
    end
    table.insert(chatRows, cur)
    pcall(closeGap, cur)
    cur:GetPropertyChangedSignal("Visible"):Connect(function()
        if cur.Visible then cur.Visible = false end
    end)
end

local function tryRemoveChat(label)
    if not trim(getText(label)):lower():find("global chat", 1, true) then return end
    local row = findChatRow(label)
    if not row or row:GetAttribute("NexusChatHidden") then return end
    row:SetAttribute("NexusChatHidden", true)
    pcall(hideChatRow, row)
end

-- ==========================================
-- 5. LOGO BERLIAN & PARTIKEL (FIX JATUH KE BAWAH)
-- ==========================================
local logoId = nil
local logoStarted = false
local logoDrawn = setmetatable({}, {__mode = "k"})
local function imgOf(o) local ok, v = pcall(function() return o.Image end) if ok and type(v) == "string" then return v end return "" end

local function drawLogo(img)
    if logoDrawn[img] or img:FindFirstChild("NexusLogo") or img.AbsoluteSize.X > 250 then return end
    logoDrawn[img] = true
    img.ImageTransparency = 1
    img:GetPropertyChangedSignal("ImageTransparency"):Connect(function() if img.ImageTransparency < 1 then img.ImageTransparency = 1 end end)
    
    local box = Instance.new("Frame")
    box.Name, box.Size, box.BackgroundTransparency, box.ZIndex = "NexusLogo", UDim2.fromScale(1, 1), 1, 50
    box.Parent = img
    
    local diamond = Instance.new("Frame")
    diamond.AnchorPoint, diamond.Position, diamond.Size, diamond.Rotation = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromScale(0.68, 0.68), 45
    diamond.BackgroundColor3, diamond.BorderSizePixel, diamond.ZIndex, diamond.Parent = Color3.new(1, 1, 1), 0, box.ZIndex, box
    Instance.new("UICorner", diamond).CornerRadius = UDim.new(0.22, 0)
    
    local grad = Instance.new("UIGradient", diamond)
    grad.Color, grad.Rotation = ColorSequence.new(Color3.fromRGB(50, 255, 100), Color3.fromRGB(10, 100, 30)), 90
    local stroke = Instance.new("UIStroke", diamond)
    stroke.Color, stroke.Thickness = Color3.fromRGB(235, 235, 245), 1.5
    
    local letter = Instance.new("TextLabel")
    letter.AnchorPoint, letter.Position, letter.Size, letter.BackgroundTransparency = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5), UDim2.fromScale(0.6, 0.6), 1
    letter.Text, letter.TextColor3, letter.Font, letter.TextScaled, letter.ZIndex, letter.Parent = "N", Color3.fromRGB(15, 15, 20), Enum.Font.GothamBlack, true, box.ZIndex + 1, box
end

local function checkImg(d) if logoId and imgOf(d) == logoId then pcall(drawLogo, d) end end

local function startLogoWatch()
    if logoStarted or not logoId then return end
    logoStarted = true
    local function sweepAll()
        for _, c in ipairs(conts) do
            for _, g in ipairs(c:GetChildren()) do
                if g:IsA("ScreenGui") then
                    for _, d in ipairs(g:GetDescendants()) do
                        if (d:IsA("ImageLabel") or d:IsA("ImageButton")) and imgOf(d) == logoId then pcall(drawLogo, d) end
                    end
                end
            end
        end
    end
    sweepAll()
    for _, c in ipairs(conts) do
        c.DescendantAdded:Connect(function(d) if d:IsA("ImageLabel") or d:IsA("ImageButton") then pcall(checkImg, d) end end)
    end
    task.spawn(function()
        for _ = 1, 10 do
            task.wait(1)
            pcall(sweepAll)
        end
    end)
end

local function discoverLogoId(gui)
    if logoId then return end
    local title = nil
    for _, d in ipairs(gui:GetDescendants()) do
        if d:IsA("TextLabel") and d.AbsoluteSize.X > 0 then
            local txt = trim(getText(d)):lower()
            if txt == NEW_TITLE:lower() or txt:find("vxeze hub") then 
                title = d 
                break 
            end
        end
    end
    local best, bestDx = nil, math.huge
    if title then
        local tc = title.AbsolutePosition + title.AbsoluteSize / 2
        for _, d in ipairs(gui:GetDescendants()) do
            if (d:IsA("ImageLabel") or d:IsA("ImageButton")) and d.AbsoluteSize.X >= 12 and d.AbsoluteSize.X <= 150 then
                local id, low, nm = imgOf(d), imgOf(d):lower(), d.Name:lower()
                if id ~= "" and not low:find("rbxthumb", 1, true) and not low:find("headshot", 1, true) and not low:find("avatar", 1, true) and not nm:find("avatar", 1, true) then
                    local c = d.AbsolutePosition + d.AbsoluteSize / 2
                    local dy, dx = math.abs(c.Y - tc.Y), tc.X - c.X
                    if dy <= math.max(30, title.AbsoluteSize.Y) and dx > 0 and dx < bestDx then best, bestDx = d, dx end
                end
            end
        end
    end
    if best then logoId = imgOf(best); pcall(startLogoWatch) end
end

local function addParticles(parent)
    if parent:FindFirstChild("NexusParticles") then return end
    local container = Instance.new("Frame")
    container.Name, container.Size, container.BackgroundTransparency = "NexusParticles", UDim2.fromScale(1, 1), 1
    container.ZIndex = 10 -- Naikin ZIndex biar keliatan
    container.ClipsDescendants = false -- MATIIN CLIP BIAR GAK KEPOTONG DI ATAS
    container.Parent = parent
    
    for i = 1, 40 do -- Tambahin jumlah partikel
        local size = math.random(2, 5)
        local star = Instance.new("Frame")
        star.Name = "Star_" .. i
        star.Size = UDim2.fromOffset(size, size)
        star.Position = UDim2.fromScale(math.random(), -0.1) -- Mulai dari atas layar
        star.BackgroundColor3 = Color3.new(1, 1, 1)
        star.BorderSizePixel = 0
        star.ZIndex = 10
        star.BackgroundTransparency = 1
        star.Parent = container
        Instance.new("UICorner", star).CornerRadius = UDim.new(1, 0)
        
        local stroke = Instance.new("UIStroke", star)
        stroke.Color, stroke.Thickness, stroke.Transparency = Color3.new(1, 1, 1), 0.5, 1
        stroke.ZIndex = 10
        
        task.spawn(function()
            while star.Parent do
                local blinkTime, moveTime = math.random(1, 3), math.random(5, 10)
                
                TweenService:Create(star, TweenInfo.new(blinkTime, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {BackgroundTransparency = 0, Size = UDim2.fromOffset(size + 1, size + 1)}):Play()
                TweenService:Create(stroke, TweenInfo.new(blinkTime), {Transparency = 0.5}):Play()
                
                -- Bergerak ke BAWAH
                local newY = star.Position.Y.Scale + 0.15
                if newY > 1.1 then newY = -0.1 end
                
                TweenService:Create(star, TweenInfo.new(moveTime, Enum.EasingStyle.Linear), {Position = UDim2.fromScale(star.Position.X.Scale + (math.random(-5, 5) / 100), newY)}):Play()
                task.wait(moveTime)
                
                TweenService:Create(star, TweenInfo.new(blinkTime, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {BackgroundTransparency = 1, Size = UDim2.fromOffset(size, size)}):Play()
                TweenService:Create(stroke, TweenInfo.new(blinkTime), {Transparency = 1}):Play()
                task.wait(blinkTime)
                
                -- Reset ke atas
                star.Position = UDim2.fromScale(math.random(), -0.1)
            end
        end)
    end
end

local function findWindow(gui)
    local title = nil
    for _, d in ipairs(gui:GetDescendants()) do
        if d:IsA("TextLabel") and d.AbsoluteSize.X > 0 then
            local txt = trim(getText(d)):lower()
            if txt == NEW_TITLE:lower() or txt:find("vxeze hub") then title = d break end
        end
    end
    if not title then return nil end
    local cur = title.Parent
    local biggest = cur
    while cur and not cur:IsA("ScreenGui") do
        if cur:IsA("GuiObject") and cur.AbsoluteSize.X > biggest.AbsoluteSize.X then biggest = cur end
        cur = cur.Parent
    end
    return biggest
end

-- ==========================================
-- 6. FUNGSI UTAMA
-- ==========================================
local function handleObject(o)
    if not o then return end
    pcall(recolorObject, o)
    
    if isText(o) then
        local t = getText(o)
        local low = t:lower()
        local lowT = trim(low)
        
        -- 1. GANTI QUICK BAR JADI NEXUS FPS BOOST
        if low:find("quick bar", 1, true) then
            if t ~= "NEXUS FPS BOOST" then pcall(function() o.Text = "NEXUS FPS BOOST" end) end
        end
        
        -- 2. TAB HIGHLIGHT
        if lowT == "home" or lowT == "steal" or lowT == "farm" or lowT == "event" or lowT == "player" or lowT == "configs" or lowT == "system" then
            local parentBtn = o
            while parentBtn and not parentBtn:IsA("GuiButton") and not parentBtn:IsA("ScreenGui") do parentBtn = parentBtn.Parent end
            if parentBtn and parentBtn:IsA("GuiButton") then pcall(hookTab, parentBtn) end
        end
        
        -- 3. GANTI WA
        if lowT == WA_LOW or low:find("discord", 1, true) then
            if lowT ~= WA_LOW then pcall(function() o.Text = WA_TEXT end) end
            local parentBtn = o.Parent
            while parentBtn and not parentBtn:IsA("GuiButton") and not parentBtn:IsA("ScreenGui") do parentBtn = parentBtn.Parent end
            if parentBtn and parentBtn:IsA("GuiButton") then
                pcall(replaceDiscordIcon, parentBtn)
                if not parentBtn:FindFirstChild("NexusWAOverlay") then
                    pcall(function() parentBtn.Active = false end) 
                    local btn = Instance.new("TextButton")
                    btn.Name, btn.BackgroundTransparency, btn.Text, btn.Size, btn.ZIndex = "NexusWAOverlay", 1, "", UDim2.fromScale(1, 1), 500
                    btn.Parent = parentBtn
                    btn.Activated:Connect(function()
                        if setclipboard then setclipboard(WA_LINK) end
                        notify("Link WA disalin!")
                    end)
                end
            end
        else
            -- 4. RENAME TEKS VXEZE
            local n = t
            n = n:gsub("Vxeze Hub V2", NEW_TITLE)
            n = n:gsub("Vxeze Hub", "NEXUS XIT")
            n = n:gsub("[Vv]xeze", "NEXUS")
            n = n:gsub("VXEZE", "NEXUS")
            if n ~= t then pcall(function() o.Text = n end) end
            
            if lowT == "global chat" or low:find("global chat", 1, true) then pcall(tryRemoveChat, o) end
        end
        
        if not o:GetAttribute("NexusHooked") then
            o:SetAttribute("NexusHooked", true)
            o:GetPropertyChangedSignal("Text"):Connect(function() pcall(handleObject, o) end)
        end
    end
end

local watched = setmetatable({}, {__mode = "k"})
local function watch(gui)
    if watched[gui] then return end
    watched[gui] = true
    
    for _, d in ipairs(gui:GetDescendants()) do pcall(handleObject, d) end
    
    task.spawn(function()
        for _ = 1, 6 do
            task.wait(1)
            pcall(discoverLogoId, gui)
            for _, r in ipairs(chatRows) do pcall(closeGap, r) end
            for _, d in ipairs(gui:GetDescendants()) do
                if isText(d) and trim(getText(d)):lower() == WA_LOW then pcall(handleObject, d) end
            end
        end
        local win = findWindow(gui)
        if win then pcall(addParticles, win) end
    end)
    
    gui.DescendantAdded:Connect(function(obj)
        task.wait(0.05)
        pcall(handleObject, obj)
    end)
end

local function isTargetUI(gui)
    local ok, res = pcall(function()
        for _, d in ipairs(gui:GetDescendants()) do
            if isText(d) and (d.Text:lower():find("vxeze", 1, true) or d.Text:lower():find("nexus xit", 1, true) or d.Text:lower():find("quick bar", 1, true)) then 
                return true 
            end
        end
        return false
    end)
    return ok and res
end

for _, c in ipairs(conts) do
    c.ChildAdded:Connect(function(ch)
        if not ch:IsA("ScreenGui") then return end
        task.spawn(function()
            for i = 1, 60 do
                if not ch.Parent then return end
                if isTargetUI(ch) then watch(ch) return end
                task.wait(0.5)
            end
        end)
    end)
    for _, ex in ipairs(c:GetChildren()) do
        if ex:IsA("ScreenGui") and isTargetUI(ex) then task.spawn(function() watch(ex) end) end
    end
end
